import { MakeLogicType, afterMount, connect, kea, path } from 'kea'

import { userLogic } from 'scenes/userLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface userDetailsLogicActions {
    loadUser: (resetOnFailure?: boolean | undefined) => {
        resetOnFailure: boolean | undefined
    } // userLogic
}

export type userDetailsLogicType = MakeLogicType<{}, userDetailsLogicActions>

export const userDetailsLogic = kea<userDetailsLogicType>([
    path(['scenes', 'settings', 'user', 'userDetailsLogic']),
    connect(() => ({
        actions: [userLogic, ['loadUser']],
    })),
    afterMount(({ actions, cache }) => {
        // Email verification (often finished in another tab) promotes pending_email server-side.
        // Refetch on mount and when the tab regains focus so this tab drops the old address and the
        // stale "Pending verification" banner instead of showing a change that already completed.
        actions.loadUser()
        cache.disposables.add(
            () => {
                const onFocus = (): void => actions.loadUser()
                window.addEventListener('focus', onFocus)
                return () => window.removeEventListener('focus', onFocus)
            },
            'reloadUserOnFocus',
            { pauseOnPageHidden: false }
        )
    }),
])
